  ('way/922572914', 'ផ្សារបឹងសាឡាងថ្មី', 'Phsar Boeung Salang Thmei', 'public_market', '12', '1207', '120707', 'ខណ្ឌឫស្សីកែវ', 'ផ្លូវ បេតុង', 'ផ្សារបឹងសាឡាងថ្មី, ផ្លូវ បេតុង, ភូមិទួលថ្ងាន់, សង្កាត់ឬស្សីកែវ, ខណ្ឌឫស្សីកែវ, រាជធានីភ្នំពេញ, 120707, ព្រះរាជាណាចក្រ​កម្ពុជា', '11.6022743', '104.9092578', null, 'verified'),
  ('way/925548653', 'Phsar Kep', 'Phsar Kep', 'public_market', '23', '0123', '012345', 'សង្កាត់កែប', 'National Road 33A', 'Mey-Mey Pharmacy, National Road 33A, សង្កាត់កែប, កែប, ខេត្តកែប, 012345, ព្រះរាជាណាចក្រ​កម្ពុជា', '10.485839', '104.3213631', null, 'verified'),
  ('way/932635568', 'Phsar Leur', 'Phsar Leur', 'public_market', '18', '1800', '180000', 'ព្រះសីហនុ', 'ផ្លូវ ២១៨', 'ផ្លូវ ២១៨, សង្កាត់បី, ព្រះសីហនុ, ខេត្តព្រះសីហនុ, 180000, ព្រះរាជាណាចក្រ​កម្ពុជា', '10.622669', '103.5300224', null, 'verified'),
